import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { signalsReportsList } from '../../generated/api'
import type { InboxOnboardingStateApi } from '../../generated/api.schemas'
import { inboxSetupLogic } from './inboxSetupLogic'

interface GeneratedReports {
    teamId: number
    count: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inboxActivationVisibilityLogicValues {
    completed: boolean // inboxSetupLogic
    currentTeamId: number | null // inboxSetupLogic
    savedState: InboxOnboardingStateApi | null // inboxSetupLogic
    activationPeriodElapsed: boolean
    generatedReports: GeneratedReports | null
    generatedReportsLoading: boolean
    now: number
    showActivationPanel: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inboxActivationVisibilityLogicActions {
    loadSetupSuccess: (
        savedState: InboxOnboardingStateApi,
        payload?: any
    ) => {
        payload?: any
        savedState: InboxOnboardingStateApi
    } // inboxSetupLogic
    setSavedState: (state: InboxOnboardingStateApi) => {
        state: InboxOnboardingStateApi
    } // inboxSetupLogic
    checkVisibility: (now?: number) => {
        now: number
    }
    loadGeneratedReports: () => any
    loadGeneratedReportsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGeneratedReportsSuccess: (
        generatedReports: GeneratedReports | null,
        payload?: any
    ) => {
        generatedReports: GeneratedReports | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inboxActivationVisibilityLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        activationPeriodElapsed: (savedState: InboxOnboardingStateApi | null, now: number) => boolean
        showActivationPanel: (
            completed: boolean,
            activationPeriodElapsed: boolean,
            currentTeamId: number | null,
            generatedReports: GeneratedReports | null
        ) => boolean
    }
}

export type inboxActivationVisibilityLogicType = MakeLogicType<
    inboxActivationVisibilityLogicValues,
    inboxActivationVisibilityLogicActions,
    Record<string, any>,
    inboxActivationVisibilityLogicMeta
>

export const inboxActivationVisibilityLogic = kea<inboxActivationVisibilityLogicType>([
    path(['products', 'signals', 'inbox', 'inboxActivationVisibilityLogic']),
    connect({
        values: [inboxSetupLogic, ['savedState', 'currentTeamId', 'completed']],
        actions: [inboxSetupLogic, ['setSavedState', 'loadSetupSuccess']],
    }),
    actions({ checkVisibility: (now: number = Date.now()) => ({ now }) }),
    loaders(({ values }) => ({
        generatedReports: [
            null as GeneratedReports | null,
            {
                loadGeneratedReports: async (): Promise<GeneratedReports | null> => {
                    const teamId = values.currentTeamId
                    if (!teamId) {
                        return null
                    }
                    const response = await signalsReportsList(String(teamId), {
                        count_only: true,
                        scope: 'entire_project',
                        status: 'ready,resolved,pending_input,suppressed',
                    })
                    return { teamId, count: response.count }
                },
            },
        ],
    })),
    reducers(() => ({ now: [Date.now(), { checkVisibility: (_, { now }) => now }] })),
    selectors({
        activationPeriodElapsed: [
            (s) => [s.savedState, s.now],
            (state: InboxOnboardingStateApi | null, now: number): boolean =>
                !!state?.completed_at && now - Date.parse(state.completed_at) >= 7 * 24 * 60 * 60_000,
        ],
        showActivationPanel: [
            (s) => [s.completed, s.activationPeriodElapsed, s.currentTeamId, s.generatedReports],
            (completed: boolean, elapsed: boolean, teamId: number | null, reports: GeneratedReports | null): boolean =>
                completed && !(elapsed && reports?.teamId === teamId && reports.count > 0),
        ],
    }),
    listeners(({ actions, values }) => ({
        checkVisibility: () => {
            if (values.showActivationPanel && values.activationPeriodElapsed && !values.generatedReportsLoading) {
                actions.loadGeneratedReports()
            }
        },
        setSavedState: () => actions.checkVisibility(),
        loadSetupSuccess: () => actions.checkVisibility(),
    })),
    afterMount(({ actions, cache }) => {
        cache.disposables.add(() => {
            actions.checkVisibility()
            const interval = setInterval(() => actions.checkVisibility(), 60_000)
            return () => clearInterval(interval)
        }, 'activationVisibility')
    }),
])
